pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address and a uint256 to be used to set block.number via vm.roll
    function testFuzz_property(address caller, uint256 someBlock) public {
        // keep caller non-zero to be a sensible EOA
        vm.assume(caller != address(0));

        // bound the block number to a reasonable range so vm.roll can be used
        uint256 b = bound(someBlock, 1, 1_000_000);
        vm.roll(uint64(b));

        // Ensure caller has exactly 10 ether to send
        vm.deal(caller, 10 ether);

        // make the call from the fuzzed caller sending exactly 10 ether
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
