pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address actor and a block timestamp offset and a block number to control divisibility by 15
    function testFuzz_property(address actor, uint64 warpSeconds, uint64 blockNum) public {
        // admissible domain: actor not zero, warpSeconds reasonable, blockNum reasonable
        vm.assume(actor != address(0));
        // keep warpSeconds and blockNum in wide bounds
        warpSeconds = uint64(bound(warpSeconds, 0, 1 days));
        blockNum = uint64(bound(blockNum, 1, 1000000));

        // set up actor with funds
        vm.deal(actor, 100 ether);

        // ensure we control block timestamp and number
        uint256 startTs = block.timestamp;
        vm.warp(startTs + warpSeconds);
        vm.roll(blockNum);

        // First call: actor sends exactly 10 ether to fallback
        vm.prank(actor);
        c.f{value: 10 ether}();

        // read pastBlockTime after first call
        uint256 first = c.pastBlockTime();

        // Call again in SAME block/time (do not change timestamp or block number)
        vm.prank(actor);
        // second call with correct value
        c.f{value: 10 ether}();

        uint256 second = c.pastBlockTime();

        // General rule: in the correct contract, the second pastBlockTime must be strictly greater than the first
        // (because the contract requires each call to observe block.timestamp > pastBlockTime before updating,
        // which enforces a monotonic progression across calls). The mutant which removed that check can allow
        // the value to stay the same when calls happen in the same timestamp context.
        assertTrue(second > first);
    }
}

