pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor (caller) and a block timestamp offset to create same-timestamp calls
    function testFuzz_property(address actor, uint256 warpOffset) public {
        vm.assume(actor != address(0));
        // keep warpOffset within a reasonable range to avoid overflow when adding to block.timestamp
        warpOffset = bound(warpOffset, 0, 1000000);

        // fund actor so it can send 10 ether
        uint256 amount = 10 ether;
        vm.deal(actor, amount);

        // ensure we start from a known pastBlockTime: call once from any sender to set it
        // do it from this test contract (has funds via deal)
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool ok1, ) = address(c).call{value: amount}("");
        require(ok1, "initialization call failed");

        // read old pastBlockTime
        uint256 old = c.pastBlockTime();

        // warp to a timestamp that ensures the timestamp is exactly the same for two calls
        // choose a target timestamp equal to old-1 (so block.timestamp+1 == old), but keep wide domain
        // compute target so that block.timestamp + 1 == old, hence block.timestamp == old - 1
        // clamp to avoid underflow
        uint256 target;
        if (old > 0) {
            target = old - 1 + warpOffset - (warpOffset % 1); // keep wide but deterministic
        } else {
            target = block.timestamp + warpOffset;
        }
        vm.warp(target);

        // First call at this timestamp from fuzzed actor
        vm.prank(actor);
        (bool okFirst, ) = address(c).call{value: amount}("");
        // it should succeed on reference contract (either because timestamp > old or equal but logic sets),
        // but we only care about successful calls; if it reverts, nothing to assert about pastBlockTime change.
        if (!okFirst) {
            // if first call reverted, try making it succeed by adjusting timestamp forward one second
            vm.warp(target + 1);
            vm.prank(actor);
            (bool okSecond, ) = address(c).call{value: amount}("");
            require(okSecond, "setup: could not obtain a successful call");
            // read new old baseline
            old = c.pastBlockTime();
            // make two rapid calls at same timestamp to check monotonicity
            vm.warp(target + 1);
            vm.prank(actor);
            (bool okA, ) = address(c).call{value: amount}("");
            vm.prank(actor);
            (bool okB, ) = address(c).call{value: amount}("");
            // if both succeed, then on correct contract the second must have increased pastBlockTime
            if (okA && okB) {
                uint256 after = c.pastBlockTime();
                assertTrue(after > old);
            } else {
                // otherwise assert trivially that after any successful call pastBlockTime > previous
                if (okA) {
                    uint256 afterA = c.pastBlockTime();
                    assertTrue(afterA > old);
                } else if (okB) {
                    uint256 afterB = c.pastBlockTime();
                    assertTrue(afterB > old);
                } else {
                    // no successful calls reachable in this branch; still keep wide domain by passing
                    assertTrue(true);
                }
            }
            return;
        }

        // After first successful call, read mid value
        uint256 mid = c.pastBlockTime();

        // Do a second call in the same block timestamp (no warp change)
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        // If the call succeeded, then on the reference contract pastBlockTime must strictly increase
        if (ok) {
            uint256 after = c.pastBlockTime();
            assertTrue(after > mid);
        } else {
            // If second call reverted on reference, then no successful second call at same timestamp is possible;
            // the universal property still holds vacuously for the successful calls we observed earlier.
            // To keep exactly one assertTrue that reads c, assert that mid > old (the successful first call increased it).
            assertTrue(mid > old);
        }
    }
}

